{
  "iteration": 5,
  "pcvs": [
    {
      "name": "query_rows",
      "expression": "query.shape[0]",
      "rationale": "Observes the query tensor's native row count directly."
    },
    {
      "name": "scheduler_bytes",
      "expression": "0 if attn_metadata is None or attn_metadata.scheduler_metadata is None else attn_metadata.scheduler_metadata.numel() * attn_metadata.scheduler_metadata.element_size()",
      "rationale": "Tests whether scheduler storage captures native task partitioning missing from earlier predictors."
    },
    {
      "name": "query_context_blocks",
      "expression": "0 if attn_metadata is None else query.shape[0] * ((attn_metadata.max_seq_len + 31) // 32)",
      "rationale": "Captures query work across rounded context blocks using tensor dimensions."
    },
    {
      "name": "sequence_count",
      "expression": "0 if attn_metadata is None else attn_metadata.seq_lens.numel()",
      "rationale": "Measures per-sequence overhead directly from the native kernel's sequence-length tensor."
    }
  ],
  "hypothesis": "Native tensor dimensions and scheduler metadata size may expose kernel work that earlier metadata-only predictors missed. All expressions use constant-time scalar or shape access."
}
